INSERT INTO `blog_articles` (`id`, `slug`, `lang`, `title`, `excerpt`, `content`, `author`, `category`, `published_at`, `image`) VALUES
('064937e6305ff025290fe5fb02113153', 'field-hockey-rules', 'ca', 'Explicació Detallada de les Regles', 'Entén el reglament oficial per gaudir més de cada partit.', '<p>L\'hoquei patins té unes regles molt específiques que el fan únic. Aquí les tens resumides per no perdre detalls.</p><h2>Temps de Joc</h2><p>Es juguen dues parts de 25 minuts a rellotge parat. Cada vegada que la bola surt o hi ha una falta, el cronòmetre s\'atura. Això fa que cada segon sigui vital.</p><h2>Sistema de Faltes Directes</h2><p>Una de les regles més emocionants és el sistema de faltes d\'equip. Quan un equip arriba a 10 faltes, el rival rep una falta directa: un cara a cara entre jugador i porter.</p><h2>Targetes i Sancions</h2><ul><li><strong>Blava:</strong> Expulsió de 2 minuts i falta directa.</li><li><strong>Vermella:</strong> Expulsió definitiva per a tot el partit.</li></ul>', 'Equip Hockey5', 'Hockey Basics', '2026-02-21 15:02:14', ''),
('064937e6305ff025290fe5fb02113153', 'field-hockey-rules', 'en', 'Explicación Detallada de las Reglas', 'Normativa y reglamento básico.', '\r\n<p>Bienvenidos a este análisis exhaustivo sobre <strong>Explicación Detallada de las Reglas</strong>, donde desglosaremos los fundamentos, mecánicas y consejos clave que transforman a un aficionado casual en un absoluto experto del hockey sobre patines, o en un jugador letal de los juegos interactivos que ofrece la plataforma de Hockey5.</p>\r\n<h2>1. Introducción al Mundo del Hockey Sobre Patines</h2>\r\n<p>El hockey sobre patines (o rink hockey) es un deporte sobre ruedas de alta velocidad practicado en más de 60 países. A diferencia del hockey sobre hielo o el hockey en línea, requiere el uso de patines tradicionales de cuatro ruedas (quads) y un stick corto terminado en una pala curva. La dinámica del juego se basa en el control rápido de la bocha (bola dura y pesada) mediante movimientos precisos.</p>\r\n<p>Con el avance tecnológico, tanto el material deportivo como la forma en la que los aficionados pueden seguir la competición (por ejemplo, mediante los juegos de <strong>Hockey5</strong>) han evolucionado drásticamente. Entender los entresijos de este deporte no solo mejora tu experiencia viéndolo, sino que expande tu capacidad de análisis.</p>\r\n<h3>1.1. Las Funciones de la Pista y el Stick</h3>\r\n<p>La pista oficial tiene dimensiones que oscilan entre 34x17 metros y 44x22 metros. Está rodeada de vallas que los jugadores utilizan para triangular pases o defender. El dominio de la pared (o valla) es uno de los primeros conceptos básicos que debe dominar un novato.</p>\r\n<p>El stick de madera o materiales compuestos es el instrumento indispensable. A diferencia de las formas en L de otros hockeys, la curva cerrada permite manejar la pelota arrastrándola, sin necesidad de golpearla repetidamente para avanzar.</p>\r\n<h2>2. Mecánicas Fundamentales</h2>\r\n<p>Las mecánicas de juego incluyen patinaje, manejo del stick, pases, tiros y defensa. Vamos a explorarlos a fondo:</p>\r\n<ul>\r\n<li><strong>Patinaje:</strong> La base absoluta de todo. Los arranques explosivos, las frenadas en seco (derrape) y el patinaje de espaldas son maniobras obligatorias.</li>\r\n<li><strong>Dominio de Bola (Dribbling):</strong> Mantener la bola pegada a la pala, moviendo las muñecas, permite regatear y cambiar el ángulo de pase.</li>\r\n<li><strong>Tiro de Pala (Arrastre):</strong> En vez de golpear como en el golf, el jugador apoya la pala en la pelota y ejerce un arrastre largo terminando en un latigazo impulsado por la flexión del cuerpo.</li>\r\n<li><strong>Pase Picado:</strong> Elevar sutilmente la bola para que supere los sticks rivales durante un pase cruzado.</li>\r\n</ul>\r\n<p>Dominar estas acciones lleva años de entrenamiento, pero para quienes juegan desde casa a través de la web, conocerlas sirve para prever movimientos tácticos y comprender las alineaciones.</p>\r\n<h3>2.1. Dinámica Específica</h3>\r\n<p>En el aspecto reglamentario, el hockey patines se caracteriza por no permitir levantar el stick por encima del nivel del hombro. Tampoco se permite que la bola sea elevada más allá de 1.5 metros, salvo cuando el portero reacciona al rebote. Estas restricciones favorecen un juego de suelo extremadamente técnico y rápido.</p>\r\n<h2>3. ¿Cómo encaja en nuestros Retos Diarios?</h2>\r\n<p>Si alguna vez has jugado a los modos <em>Grid</em>, <em>Wordle</em> o <em>Adivina el jugador</em> de Hockey5, te habrás dado cuenta de que estos juegos nacen a partir de estadísticas vitales del juego. Los grandes pasadores, los goleadores o los defensas férreos tienen trayectorias que son puestas a prueba a diario.</p>\r\n<p>Un equipo se divide comúnmente en un portero, dos defensas (que rotan) y dos delanteros (que suelen atacar en asimetría). Cuando se te pide en el juego identificar el equipo o adivinar el quinteto de la <strong>OK Liga</strong> o la <strong>Liga Placard</strong>, debes pensar en esta estructura.</p>\r\n<h2>4. Reglas Avanzadas y Excepciones</h2>\r\n<p>Los tiros libres directos y los penaltis juegan un rol crucial. Cuando se comete una falta grave o un equipo acumula 10 o 15 faltas de equipo a lo largo del partido (sistema similar al baloncesto o fútbol sala), el rival se beneficia de un tiro libre directo.</p>\r\n<p>Esta jugada de \"uno contra el portero\" sin barrera requiere nervios de acero. El especialista suele aproximarse despacio, moviendo el stick rítmicamente (haciendo <em>pick and roll</em> de bola) para engañar al meta y superarlo con un gancho (dribbling final) o un remate picado por la escuadra.</p>\r\n<h2>5. El Impacto Global y las Competiciones</h2>\r\n<p>Los campeonatos mundiales y la Liga Europea mantienen a los fanáticos al borde del asiento. Países como España, Portugal, Argentina e Italia han convertido a este deporte en casi una religión. Cada fin de semana, miles de aficionados consumen contenido de estas ligas y luego ponen a prueba su saber en Hockey5.</p>\r\n<h2>6. Conclusión</h2>\r\n<p>Al dominar estas ideas expuestas en esta guía de conocimiento, tu comprensión del juego alcanzará nuevos horizontes. El hockey sobre patines es una sinfonía de patines chirriando contra el parqué, el incesante golpeteo de las bolas contra la madera y un derroche táctico. Sigue disfrutando cada día y reta tu mente mientras exploras el fascinante legado deportivo de la pista.</p>\r\n        ', 'Equipo Hockey5', 'Hockey Basics', '2026-02-21 15:02:14', ''),
('064937e6305ff025290fe5fb02113153', 'field-hockey-rules', 'es', 'Explicación Detallada de las Reglas', 'Entiende el reglamento para disfrutar del juego sin confusiones.', '<p>El hockey sobre patines tiene reglas muy específicas que buscan mantener la velocidad del juego pero garantizando la seguridad.</p><h2>La Regla de los 5 Segundos</h2><p>Un equipo no puede retener la bola detrás de su propia portería por más de 5 segundos. Esto obliga a sacar la bola jugada y evita el juego pasivo.</p><h2>Faltas de Equipo</h2><p>Cada 10 faltas cometidas por un equipo, el rival dispone de una <strong>Falta Directa</strong>. Este es un duelo uno contra uno entre el jugador y el portero desde una distancia de 7.4 metros.</p><h2>Tarjetas y Sanciones</h2><ul><li><strong>Tarjeta Azul:</strong> Expulsión de 2 minutos y falta directa para el rival.</li><li><strong>Tarjeta Roja:</strong> Expulsión definitiva del partido.</li></ul><p>Dominar estas reglas es esencial para entender las jugadas polémicas que a menudo comentamos en la comunidad de Hockey5.</p>', 'Equipo Hockey5', 'Hockey Basics', '2026-02-21 15:02:14', ''),
